// Builds the full picture of ONE client from every Lumière sheet (one read = one consistent snapshot).
// Arma la foto completa de UNA clienta con todas las hojas de Lumière (una lectura = una foto consistente).
// Input / entrada: { lead_id } o { whatsapp } (opcional: max_mensajes, default 30)
const input = $('When Called').first().json;
const ranges = $input.first().json.valueRanges || [];
const SHEETS = ['Leads', 'Conversaciones', 'Citas', 'Escalamientos', 'Servicios', 'Negocio', 'Calificaciones']; // mismo orden que la URL

// Filas -> objetos con encabezado, + row_number (fila real en el Sheet, para hacer update después)
const toRows = (vr) => {
  const v = (vr && vr.values) || [];
  const h = v[0] || [];
  return v.slice(1)
    .map((r, i) => { const o = { row_number: i + 2 }; h.forEach((k, j) => { o[k] = r[j] === undefined ? '' : String(r[j]); }); return o; })
    .filter(o => h.some(k => o[k] !== ''));
};
const t = {};
SHEETS.forEach((s, i) => { t[s] = toRows(ranges[i]); });

// Negocio (clave/valor) -> objeto; Servicios activos con números reales
const negocio = {};
t.Negocio.forEach(r => { if (r.clave) negocio[r.clave] = r.valor; });
const servicios = t.Servicios
  .filter(s => String(s.activo).toLowerCase() === 'si')
  .map(s => ({ ...s, precio_desde_usd: Number(s.precio_desde_usd) || 0, duracion_min: Number(s.duracion_min) || 60 }));

const tz = negocio.zona_horaria || 'America/Phoenix';
const ahora = $now.setZone(tz).toFormat('yyyy-MM-dd HH:mm:ss');
const ahoraMin = ahora.slice(0, 16); // 'yyyy-MM-dd HH:mm', mismo formato que Citas.inicio

// Buscar a la clienta por lead_id o por WhatsApp (comparando solo dígitos: Sheets a veces quita el +)
const digits = v => String(v || '').replace(/\D/g, '');
const wantId = String(input.lead_id || '').trim();
const wantWa = digits(input.whatsapp);
const lead = t.Leads.find(l => (wantId && l.lead_id === wantId) || (wantWa && digits(l.whatsapp) === wantWa)) || null;

if (!lead) {
  return [{ json: { found: false, query: { lead_id: wantId, whatsapp: String(input.whatsapp || '') }, negocio, servicios, ahora } }];
}

const mine = rows => rows.filter(r => r.lead_id === lead.lead_id);
const ACTIVE = ['agendada', 'confirmada', 'reprogramada'];
const citas = mine(t.Citas).sort((a, b) => (a.inicio < b.inicio ? -1 : 1));
const cita_activa = citas.find(c => ACTIVE.includes(c.estado) && c.inicio >= ahoraMin) || null;
const escalamientos = mine(t.Escalamientos);
const escalamiento_abierto = escalamientos.find(e => e.estado === 'abierto') || null;
const todos = mine(t.Conversaciones).filter(m => m.rol !== 'alerta_equipo'); // las alertas al equipo no son parte del chat
const mensajes = todos.slice(-(Number(input.max_mensajes) || 30));
const ya_vino = citas.some(c => c.estado === 'asistio') || lead.primera_vez === 'no';
// P34: latest attended visit (last 7 days) without a rating yet / última cita atendida (7 días) aún sin calificar
const calificaciones = mine(t.Calificaciones);
const calificadas = new Set(calificaciones.map(r => r.cita_id));
const hace7 = $now.setZone(tz).minus({ days: 7 }).toFormat('yyyy-MM-dd HH:mm');
const cita_por_calificar = [...citas].reverse().find(c => c.estado === 'asistio' && !calificadas.has(c.cita_id) && (c.fin || c.inicio) >= hace7) || null;

return [{ json: {
  found: true,
  lead,                                   // fila de Leads (con row_number)
  es_clienta_nueva: !ya_vino,             // nueva -> agenda la consulta gratis (SRV-00)
  servicio_interes: servicios.find(s => s.nombre_es === lead.tratamiento) || null,
  cita_activa,                            // próxima cita vigente o null
  citas,                                  // todas sus citas
  escalamiento_abierto,                   // si existe, el agente NO responde
  cita_por_calificar,                     // P34: cita atendida sin nota (o null)
  calificaciones,                         // P34: sus notas 1-5
  escalamientos_total: escalamientos.length,
  mensajes,                               // últimos N de Conversaciones
  mensajes_total: todos.length,
  negocio,
  servicios,
  ahora
} }];
